package br.local.fmlab;

import android.app.*;
import android.content.*;
import android.content.SharedPreferences;
import android.graphics.drawable.GradientDrawable;
import android.os.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.io.*;

final class LabFeatures {
 interface Host {int frequency();boolean isOn();String station();int source();int low();int high();void tune(int frequency);void message(String s);}
 private final Activity app;private final SharedPreferences prefs;private final Host host;
 private TextView progress;private Button recordButton;private Measurement measure;
 private boolean recording=false;private StringBuilder csv=new StringBuilder();private int rows=0;private long recordStart=0,lastUi=0;
 private String exportText="";private static final int EXPORT=77;
 LabFeatures(Activity a,SharedPreferences p,Host h){app=a;prefs=p;host=h;}
 private int dp(int v){return (int)(app.getResources().getDisplayMetrics().density*v+.5);}
 private LinearLayout column(){LinearLayout p=new LinearLayout(app);p.setOrientation(1);return p;}
 private TextView text(LinearLayout p,String s,int size){TextView t=new TextView(app);t.setText(s);t.setTextSize(size);t.setTextColor(0xffbecce0);t.setPadding(0,dp(5),0,dp(5));p.addView(t);return t;}
 private GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 private LinearLayout row(LinearLayout p){LinearLayout r=new LinearLayout(app);p.addView(r);return r;}
 private Button button(LinearLayout p,String name,View.OnClickListener click){Button b=new Button(app);b.setText(name);b.setTextColor(0xffe6edf7);b.setTextSize(12);b.setAllCaps(false);b.setBackground(shape(0xff22334b,10));b.setOnClickListener(click);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(48),1);lp.setMargins(dp(3),dp(5),dp(3),dp(3));p.addView(b,lp);return b;}
 LinearLayout addTo(LinearLayout parent){LinearLayout panel=column();panel.setPadding(dp(16),dp(12),dp(16),dp(14));panel.setBackground(shape(0xff101d2e,18));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,dp(12));parent.addView(panel,lp);text(panel,"FAVORITOS E TESTES DE COBERTURA",11).setLetterSpacing(.1f);
  LinearLayout fav=row(panel);button(fav,"Salvar favorito",new View.OnClickListener(){public void onClick(View v){saveFavorite();}});button(fav,"Favoritos",new View.OnClickListener(){public void onClick(View v){showFavorites();}});
  LinearLayout tests=row(panel);button(tests,"Medir local · 10 s",new View.OnClickListener(){public void onClick(View v){startMeasure();}});button(tests,"Comparar locais",new View.OnClickListener(){public void onClick(View v){showMeasurements();}});
  LinearLayout rec=row(panel);recordButton=button(rec,"Registrar métricas",new View.OnClickListener(){public void onClick(View v){toggleRecording();}});button(rec,"Exportar CSV",new View.OnClickListener(){public void onClick(View v){chooseExport();}});
  progress=text(panel,"Salve medições para comparar cômodos e posições da antena.",11);
  final CheckBox awake=new CheckBox(app);awake.setText("Manter a tela ligada durante os testes");awake.setTextSize(12);awake.setTextColor(0xffbecce0);awake.setChecked(prefs.getBoolean("keepScreenOn",false));panel.addView(awake);applyAwake(awake.isChecked());awake.setOnCheckedChangeListener(new CompoundButton.OnCheckedChangeListener(){public void onCheckedChanged(CompoundButton b,boolean enabled){prefs.edit().putBoolean("keepScreenOn",enabled).apply();applyAwake(enabled);}});
  text(panel,"Medições usam a frequência solicitada no FM Lab. Não calculam potência de transmissão nem distância.",10);
  return panel;
 }
 private void applyAwake(boolean enabled){if(enabled)app.getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);else app.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}
 private JSONArray array(String key){try{return new JSONArray(prefs.getString(key,"[]"));}catch(Exception e){return new JSONArray();}}
 private boolean ready(){if(!host.isOn()){host.message("Ligue e conecte o rádio antes de medir");return false;}if(host.frequency()==0){host.message("Sintonize pelo FM Lab para identificar a frequência desta medição");return false;}return true;}
 private String mhz(int f){return String.format(Locale.US,"%.1f MHz",f/1000.0);}
 private void prompt(String title,String initial,final NameAction action){final EditText name=new EditText(app);name.setText(initial);name.setSingleLine();name.setSelectAllOnFocus(true);name.setPadding(dp(20),dp(12),dp(20),dp(12));final AlertDialog dialog=new AlertDialog.Builder(app).setTitle(title).setView(name).setPositiveButton("Salvar",null).setNegativeButton("Cancelar",null).create();dialog.setOnShowListener(new DialogInterface.OnShowListener(){public void onShow(DialogInterface d){dialog.getButton(-1).setOnClickListener(new View.OnClickListener(){public void onClick(View v){String s=name.getText().toString().trim();if(s.length()==0||s.length()>80){name.setError("Use um nome entre 1 e 80 caracteres");return;}action.run(s);dialog.dismiss();}});}});dialog.show();}
 interface NameAction {void run(String name);}
 private void saveFavorite(){if(!ready())return;final int f=host.frequency();prompt("Nome do favorito",mhz(f),new NameAction(){public void run(String name){try{JSONArray old=array("favorites"),next=new JSONArray();for(int i=0;i<old.length();i++)if(old.getJSONObject(i).optInt("frequency")!=f)next.put(old.getJSONObject(i));JSONObject j=new JSONObject();j.put("frequency",f);j.put("name",name);next.put(j);while(next.length()>40)next=without(next,0);prefs.edit().putString("favorites",next.toString()).apply();host.message("Favorito salvo: "+name);}catch(Exception e){host.message("Falha ao salvar favorito");}}});}
 private JSONArray without(JSONArray a,int selected){JSONArray out=new JSONArray();for(int i=0;i<a.length();i++)if(i!=selected)out.put(a.opt(i));return out;}
 private void showFavorites(){final JSONArray a=array("favorites");if(a.length()==0){host.message("Nenhum favorito salvo ainda");return;}String[] names=new String[a.length()];for(int i=0;i<a.length();i++){JSONObject j=a.optJSONObject(i);names[i]=j.optString("name")+" · "+mhz(j.optInt("frequency"));}
  new AlertDialog.Builder(app).setTitle("Favoritos").setItems(names,new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,final int which){final JSONObject j=a.optJSONObject(which);new AlertDialog.Builder(app).setTitle(j.optString("name")).setItems(new String[]{"Sintonizar "+mhz(j.optInt("frequency")),"Excluir favorito"},new DialogInterface.OnClickListener(){public void onClick(DialogInterface q,int action){if(action==0)host.tune(j.optInt("frequency"));else prefs.edit().putString("favorites",without(a,which).toString()).apply();}}).show();}}).setNegativeButton("Fechar",null).show();
 }
 private void startMeasure(){if(measure!=null){host.message("Uma medição já está em andamento");return;}if(!ready())return;prompt("Local / posição da antena","Sala · antena atual",new NameAction(){public void run(String name){if(!ready())return;measure=new Measurement(SystemClock.elapsedRealtime(),host.frequency(),name,host.source(),host.low(),host.high());progress.setText("Medindo "+name+" · permaneça no local por 10 s");}});}
 void sample(Integer rss,Integer sin,long now,boolean on){if(!on){interrupt("Rádio desligado");return;}
  if(measure!=null){if(host.frequency()!=measure.frequency){measure=null;progress.setText("Medição cancelada: sintonia alterada");}else if(now-measure.started<=10000)measure.add(rss,sin);}
  if(recording){csv.append(System.currentTimeMillis()).append(';').append(now-recordStart).append(';').append(host.frequency()).append(';').append(rss==null?"":rss).append(';').append(sin==null?"":sin).append(';').append(csvField(host.station())).append('\n');rows++;if(rows>=12000){recording=false;recordButton.setText("Registrar métricas");progress.setText("Limite de 12.000 leituras atingido · exporte o CSV");}}
  if(now-lastUi>1000&&recording){lastUi=now;progress.setText("Registro ativo · "+rows+" leituras · "+((now-recordStart)/1000)+" s");}
  tick(now);
 }
 void tick(long now){if(measure==null)return;long remaining=10000-(now-measure.started);if(remaining>0){if(!recording)progress.setText("Medindo "+measure.name+" · faltam "+((remaining+999)/1000)+" s · "+measure.cycles+" leituras");return;}Measurement m=measure;measure=null;if(m.rssi.n<2&&m.sinr.n<2){progress.setText("Medição descartada: faltaram amostras válidas");return;}
  try{JSONObject j=new JSONObject();j.put("name",m.name);j.put("frequency",m.frequency);j.put("timestamp",System.currentTimeMillis());j.put("duration_ms",now-m.started);j.put("cycles",m.cycles);j.put("rssi",stats(m.rssi));j.put("sinr",stats(m.sinr));j.put("poor",m.poor);j.put("classified",m.classified);j.put("source",m.source==0?"SINR":"RSSI");j.put("low",m.low);j.put("high",m.high);JSONArray old=array("measurements"),next=new JSONArray();for(int i=Math.max(0,old.length()-49);i<old.length();i++)next.put(old.opt(i));next.put(j);prefs.edit().putString("measurements",next.toString()).apply();progress.setText("Salvo: "+m.name+" · "+m.cycles+" leituras · veja Comparar locais");}catch(Exception e){progress.setText("Não foi possível salvar a medição");}
 }
 private JSONObject stats(Measurement.Stats s)throws JSONException{JSONObject j=new JSONObject();j.put("n",s.n);j.put("mean",s.n==0?JSONObject.NULL:s.mean);j.put("min",s.n==0?JSONObject.NULL:s.min);j.put("max",s.n==0?JSONObject.NULL:s.max);j.put("sd",s.n<2?JSONObject.NULL:s.sd());return j;}
 private String val(JSONObject j,String key){return j==null||j.isNull(key)?"—":String.format(Locale.US,"%.1f",j.optDouble(key));}
 private void showMeasurements(){final JSONArray a=array("measurements");if(a.length()==0){host.message("Faça uma medição de 10 segundos para comparar os locais");return;}final ArrayList<JSONObject> sorted=new ArrayList<JSONObject>();for(int i=0;i<a.length();i++)sorted.add(a.optJSONObject(i));Collections.sort(sorted,new Comparator<JSONObject>(){public int compare(JSONObject x,JSONObject y){int f=Integer.compare(x.optInt("frequency"),y.optInt("frequency"));if(f!=0)return f;double sx=x.optJSONObject("sinr").optDouble("mean",-Double.MAX_VALUE),sy=y.optJSONObject("sinr").optDouble("mean",-Double.MAX_VALUE);return Double.compare(sy,sx);}});
  StringBuilder b=new StringBuilder("Agrupado por frequência solicitada; maior SINR médio primeiro. Compare o mesmo aparelho e mantenha o cabo de fone na mesma posição.\n\n");for(JSONObject j:sorted){JSONObject r=j.optJSONObject("rssi"),s=j.optJSONObject("sinr");b.append(j.optString("name")).append(" · ").append(mhz(j.optInt("frequency"))).append('\n').append("SINR médio ").append(val(s,"mean")).append(" · RSSI médio ").append(val(r,"mean")).append('\n').append("Variação RSSI (desvio) ").append(val(r,"sd")).append(" · leituras ").append(j.optInt("cycles")).append('\n').append("Ruim: ").append(j.optInt("poor")).append('/').append(j.optInt("classified")).append(" classificadas por ").append(j.optString("source")).append(" < ").append(j.optInt("low")).append("\n\n");}
  ScrollView scroll=new ScrollView(app);TextView t=new TextView(app);t.setPadding(dp(20),dp(8),dp(20),dp(8));t.setTextColor(0xffe6edf7);t.setTextSize(13);t.setText(b);scroll.addView(t);new AlertDialog.Builder(app).setTitle("Medições de locais · "+a.length()).setView(scroll).setPositiveButton("Fechar",null).show();
 }
 private void toggleRecording(){if(recording){recording=false;recordButton.setText("Registrar métricas");progress.setText("Registro parado · "+rows+" leituras · exporte antes de fechar o app");return;}if(!ready())return;if(rows>0){new AlertDialog.Builder(app).setTitle("Iniciar novo registro?").setMessage("O registro em memória será substituído. Exporte o CSV antes, se quiser guardar.").setPositiveButton("Novo registro",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){startRecording();}}).setNegativeButton("Cancelar",null).show();}else startRecording();}
 private void startRecording(){if(!ready())return;recording=true;rows=0;recordStart=SystemClock.elapsedRealtime();csv=new StringBuilder("timestamp_epoch_ms;elapsed_ms;frequency_requested_khz;rssi_raw;sinr_raw;station_ps\n");recordButton.setText("Parar registro");progress.setText("Registrando métricas · máximo 12.000 leituras");}
 void interrupt(String why){if(measure!=null){measure=null;progress.setText("Medição cancelada · "+why);}if(recording){recording=false;recordButton.setText("Registrar métricas");progress.setText("Registro interrompido · "+why+" · "+rows+" leituras disponíveis para exportar");}}
 void pause(){interrupt("tela pausada");}
 static String csvField(String s){if(s==null)s="";s=s.replace('\r',' ').replace('\n',' ');String trimmed=s.trim();if(trimmed.length()>0&&"=+-@".indexOf(trimmed.charAt(0))>=0)s="'"+s;return "\""+s.replace("\"","\"\"")+"\"";}
 private void chooseExport(){new AlertDialog.Builder(app).setTitle("Exportar dados").setItems(new String[]{"Registro contínuo de RSSI / SINR","Medições de locais salvas"},new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){if(which==0){if(rows==0){host.message("Registre algumas métricas antes de exportar");return;}interrupt("exportação");exportText=csv.toString();}else{JSONArray a=array("measurements");if(a.length()==0){host.message("Nenhuma medição salva");return;}StringBuilder b=new StringBuilder("name;frequency_requested_khz;timestamp_epoch_ms;rssi_mean;rssi_sd;sinr_mean;cycles;poor;classified;quality_source;quality_low;quality_high\n");for(int i=0;i<a.length();i++){JSONObject j=a.optJSONObject(i);b.append(csvField(j.optString("name"))).append(';').append(j.optInt("frequency")).append(';').append(j.optLong("timestamp")).append(';').append(val(j.optJSONObject("rssi"),"mean")).append(';').append(val(j.optJSONObject("rssi"),"sd")).append(';').append(val(j.optJSONObject("sinr"),"mean")).append(';').append(j.optInt("cycles")).append(';').append(j.optInt("poor")).append(';').append(j.optInt("classified")).append(';').append(j.optString("source")).append(';').append(j.optInt("low")).append(';').append(j.optInt("high")).append('\n');}exportText=b.toString();}
  try{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("text/csv");i.putExtra(Intent.EXTRA_TITLE,"FM-Lab-"+(which==0?"registro":"locais")+"-"+System.currentTimeMillis()+".csv");app.startActivityForResult(i,EXPORT);}catch(Exception e){host.message("Nenhum seletor de arquivos disponível");}}}).setNegativeButton("Cancelar",null).show();}
 boolean onResult(int request,int result,Intent data){if(request!=EXPORT)return false;if(result!=Activity.RESULT_OK||data==null||data.getData()==null){host.message("Exportação cancelada · dados mantidos no app");return true;}try{OutputStream out=app.getContentResolver().openOutputStream(data.getData());if(out==null)throw new IOException("Arquivo indisponível");try{out.write(exportText.getBytes("UTF-8"));}finally{out.close();}host.message("CSV exportado");}catch(Exception e){host.message("Falha na exportação: "+e.getMessage());}return true;}
}
